def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value in (1, 2)]
    start = next((p for p in points if grid[p[0]][p[1]] == 1), None)
    target = next((p for p in points if grid[p[0]][p[1]] == 2), None)
    if start is None or target is None:
        return out
    r, c = start
    tr, tc = target
    dr = 1 if tr > r else -1 if tr < r else 0
    dc = 1 if tc > c else -1 if tc < c else 0
    # Travel diagonally toward the target while both coordinates still differ,
    # then finish along the remaining axis; stop one cell short of the 2.
    while r + dr != tr and c + dc != tc:
        r += dr
        c += dc
        out[r][c] = 3
    while (abs(tr - r) + abs(tc - c)) > 1 and (r, c) != target:
        if r != tr and c == tc:
            r += dr
        elif c != tc and r == tr:
            c += dc
        elif abs(tr - r) > 1 and c == tc:
            r += dr
        elif abs(tc - c) > 1 and r == tr:
            c += dc
        else:
            # One coordinate is already adjacent while the other still differs;
            # continue on the axis that does not step onto the target.
            if abs(tr - r) > 1:
                r += dr
            elif abs(tc - c) > 1:
                c += dc
            else:
                break
        if (r, c) != target:
            out[r][c] = 3
    return out
